import dataclasses
import difflib
import json
import os
import re
import sys
import zoneinfo
from pathlib import Path

# TO CONFIGURE, DO NOT EDIT THIS FILE. There are two config files:
#   finbot.env       the startup env: DATA_DIR, ip, port, credentials and the mode of each network. Never read by the
#                    bot: the launcher loads it into the environment (systemd EnvironmentFile=, docker --env-file,
#                    init.d `set -a; . finbot.env`). A change needs a restart.
#   settings.conf    how the bot behaves: <DATA_DIR>/settings.conf, read by the bot itself at start and on every
#                    reload (SIGHUP).

REPO_DIR = Path(__file__).resolve().parent.parent

SETTINGS_FILE = 'settings.conf'
TEMPLATE = REPO_DIR / 'defaults' / SETTINGS_FILE # every key commented out at its default; finbot never reads it
HOME_CHAT = ("each chat has its own jobs (/jobs), which post there as the bot, and an error that belongs to no chat"
	' goes to the log; delete the line')
RETIRED = { # keys of either file that do nothing any more: accepted, so that they never stop a start, with a note at
	# start saying what to do instead
	'alliterate': 'delete the line',
	'chunk_maxlines': 'delete the line',
	'performance_use_sharesight': 'delete the line (price performance comes from Yahoo)',
	'slack_webhook': "each chat's jobs (/jobs) post there as the bot (slackBotToken); delete the line",
	'discord_webhook': "each chat's jobs (/jobs) post there as the bot (discordBotToken); delete the line",
	'telegramChatID': HOME_CHAT,
	'slackChannelID': HOME_CHAT,
	'discordChannelID': HOME_CHAT,
	'scheduler': 'the scheduler is always on, and a schedule without jobs runs nothing; delete the line',
	'debug': 'log_level sets what the log shows (INFO by default; DEBUG adds cache hits); delete the line',
	'sharesight_code': 'Sharesight needs only sharesight_client_id and sharesight_client_secret; delete the line',
}
RENAMED = { # startup keys under a new name: the old still works (the new wins where both are set), with a note at start
	'telegramOutgoingToken': 'telegramSecretToken', # Telegram calls it the secret token
}
SERVICE_DATA_DIR = '/var/lib/private/finbot' # systemd's state directory of finbot.service (StateDirectory=)
LOG_LEVELS = ('ERROR', 'WARN', 'INFO', 'DEBUG') # log_level's values, the most severe first (lib/log.py)


class ConfigError(Exception):
	"""One or more problems, each already naming the file and line. `errors` is the list."""
	def __init__(self, errors):
		"""errors: one message or a list of them."""
		self.errors = [errors] if isinstance(errors, str) else list(errors)
		super().__init__('\n'.join(self.errors))


def key_problem(key, this_keys, other_keys, other_file):
	"""Why `key` may not be in this file, or None."""
	if key in this_keys:
		return None
	if key in other_keys:
		why = ' (a change needs a restart)' if other_file == 'finbot.env' else ' (it is reloadable)'
		return f"{key} belongs in {other_file}" + why
	near = difflib.get_close_matches(key, list(this_keys) + list(other_keys), n=1)
	return f'unknown key {key}' + (f' (did you mean {near[0]}?)' if near else '')


def parse_assignments(text, path, classify):
	"""KEY=value lines -> ({key: value}, [errors]). Blank and # lines are skipped, one pair of matching quotes is
	stripped, `classify(key)` returns a reason to refuse the key. Every error names the file and line."""
	values, errors = {}, []
	for number, raw in enumerate(text.splitlines(), 1):
		line = raw.strip()
		if not line or line.startswith('#'):
			continue
		where = f'{path} line {number}'
		if line.startswith('['):
			errors.append(f'{where}: no sections, one KEY=value per line')
			continue
		key, sep, value = line.partition('=')
		key = key.strip()
		if not sep or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
			errors.append(f'{where}: expected KEY=value')
			continue
		if problem := classify(key):
			errors.append(f'{where}: {problem}')
			continue
		value = value.strip()
		if len(value) >= 2 and value[0] == value[-1] and value[0] in '\'"':
			value = value[1:-1]
		if key in values:
			errors.append(f'{where}: {key} is set twice')
			continue
		values[key] = value
	return values, errors


def read_text(path):
	"""The file's text, None if it does not exist. Raises ConfigError if it cannot be read."""
	try:
		return Path(path).read_text(encoding='utf-8')
	except FileNotFoundError:
		return None
	except (OSError, UnicodeDecodeError) as e:
		raise ConfigError(f'cannot read {path}: {getattr(e, "strerror", None) or e}')


def read_assignments(path, keys, other_keys, other_file):
	"""{key: value} of a config file of KEY=value lines, each key one of `keys` or RETIRED (one of `other_keys` is said
	to belong in other_file), or None where there is no such file. Raises ConfigError for anything wrong with it."""
	text = read_text(path)
	if text is None:
		return None
	values, errors = parse_assignments(text, path, lambda key: None if key in RETIRED or key in RENAMED else
		key_problem(key, keys, other_keys, other_file))
	if errors:
		raise ConfigError(errors)
	return values


def read_settings(path):
	"""{key: value} of a settings.conf, None if there is none. Raises ConfigError for anything wrong with it."""
	return read_assignments(path, SETTING_KEYS, STARTUP_KEYS, 'finbot.env')


def template_keys():
	"""The keys that defaults/settings.conf sets: its lines that are not commented out, none as shipped. finbot never
	reads the template, so a key set there does nothing; an unreadable template sets nothing either."""
	try:
		return list(parse_assignments(read_text(TEMPLATE) or '', TEMPLATE, lambda key: None)[0])
	except ConfigError:
		return []


def template_note(settings_path):
	"""What to tell whoever set keys in defaults/settings.conf, which finbot never reads: to set them in
	settings_path instead, made first with util/sync_defaults.py when there is none. None when the template sets
	nothing, as shipped."""
	keys = template_keys()
	if not keys:
		return None
	fix = (f'edit {settings_path} instead' if os.path.isfile(settings_path) else
		f'run util/sync_defaults.py --apply, then edit {settings_path}')
	return f"defaults/settings.conf sets {', '.join(keys)}, but finbot never reads it: {fix}"


def read_startup_file(path):
	"""{key: value} of a finbot.env, for checking it offline (the bot never reads this file). Raises ConfigError."""
	values = read_assignments(path, STARTUP_KEYS, SETTING_KEYS, SETTINGS_FILE)
	if values is None:
		raise ConfigError(f'{path} does not exist')
	return values


TRUE_WORDS = ('true', '1', 't', 'yes', 'y', 'on')
FALSE_WORDS = ('false', '0', 'f', 'no', 'n', 'off')


class _Reader:
	"""Typed reads from a getenv(name, default); a bad value is remembered, the default used, and all problems raised
	together. A blank value means unset: the default."""
	def __init__(self, getenv):
		"""getenv(name, default) supplies the values; the problems found collect in `errors` until check()."""
		self.getenv = getenv
		self.errors = []

	def value(self, name, default):
		"""The raw value, or default when it is unset or blank."""
		value = self.getenv(name, default)
		return default if value == '' else value

	def str(self, name, default=None):
		"""A text setting."""
		return self.value(name, default)

	def blankable(self, name, default):
		"""A text setting where a blank value means none (''), not the default."""
		value = self.getenv(name, default)
		return '' if value is None else str(value).strip()

	def bool(self, name, default):
		"""A boolean: true/false, yes/no, on/off, 1/0 or t/f in any case; anything else is an error, giving default."""
		value = self.value(name, default)
		word = str(value).strip().lower()
		if word in TRUE_WORDS or word in FALSE_WORDS:
			return word in TRUE_WORDS
		self.errors.append(f"{name}={value!r} is not true or false")
		return default

	def number(self, kind, name, default):
		"""A setting of type `kind` (int or float). A value that is not one is an error, and gives default."""
		value = self.value(name, default)
		try:
			return kind(value)
		except ValueError:
			self.errors.append(f"{name}={value!r} is not a {'whole number' if kind is int else 'number'}")
			return kind(default)

	def int(self, name, default):
		"""A whole-number setting."""
		return self.number(int, name, default)

	def float(self, name, default):
		"""A number setting."""
		return self.number(float, name, default)

	def choice(self, name, default, choices):
		"""One of choices, in any case, as choices spells it; anything else is an error, giving default."""
		value = str(self.value(name, default)).strip()
		if found := next((choice for choice in choices if choice.lower() == value.lower()), None):
			return found
		self.errors.append(f"{name}={self.getenv(name, default)!r} is not one of {', '.join(choices)}")
		return default

	def zone(self, name, default):
		"""A time zone's name as zoneinfo knows it (Australia/Sydney, UTC); anything else is an error, giving default:
		a zone read wrong would schedule every new job in UTC."""
		value = str(self.value(name, default)).strip()
		try:
			zoneinfo.ZoneInfo(value)
			return value
		except (ValueError, zoneinfo.ZoneInfoNotFoundError):
			self.errors.append(f"{name}={value!r} is not a time zone such as Australia/Sydney or UTC")
			return default

	def words(self, name, default):
		"""A list of words, separated by spaces: a tuple of them."""
		value = self.value(name, default)
		return tuple(value.split()) if isinstance(value, str) else tuple(value)

	def blankable_words(self, name, default):
		"""A list of words where a blank value means none (an empty tuple), not the default: unset keeps the default."""
		value = self.getenv(name, None)
		return default if value is None else tuple(str(value).split())

	def check(self):
		"""Raise ConfigError with every problem found so far."""
		if self.errors:
			raise ConfigError(self.errors)


@dataclasses.dataclass(frozen=True)
class Env:
	"""The startup settings: finbot.env, which the launcher loads into the environment; fixed for the process. Each key
	is a field with its default, read as its type says (startup_values), but those worked out from them (DERIVED)."""
	ip: str = '127.0.0.1'
	port: int = 5000
	scheduler_catchup: int = 5 # minutes: a run missed while the bot was down still fires if it was due this recently
	sharesight_client_id: str = '' # '' without Sharesight: a chat's reports then cover its watchlist alone
	sharesight_client_secret: str = ''
	slackBotToken: str = '' # '' when unset, like the rest below
	slackAppToken: str = '' # xapp-: Socket Mode, Slack's pull mode (without slackOutgoingWebhook)
	slackOutgoingToken: str = ''
	slackOutgoingWebhook: str = ''
	slackSigningSecret: str = ''
	telegramBotToken: str = ''
	telegramSecretToken: str = ''
	telegramOutgoingWebhook: str = ''
	discordBotToken: str = ''
	discordOutgoingWebhook: str = '' # the interactions endpoint URL (http mode); unset, finbot keeps to the gateway
	discordPublicKey: str = '' # the app's key, which checks the signature of each interaction posted to the endpoint
	data_dir: str = str(REPO_DIR / 'var') # DATA_DIR, else systemd's STATE_DIRECTORY: each chat's jobs, the watchlist,
	# seen trades, ratings, settings.conf; a relative one is in the checkout, wherever finbot starts
	cache_dir: str = str(REPO_DIR / 'var' / 'cache') # data_dir/cache
	telegram_api: str = '' # the Bot API's base URL for telegramBotToken ('' without one): a method's name follows it

	@property
	def settings_path(self):
		"""Where settings.conf is read from: the data dir."""
		return self.data_dir + '/' + SETTINGS_FILE


DERIVED = ('data_dir', 'cache_dir', 'telegram_api') # Env's fields worked out from its keys, not keys of their own
STARTUP_KEYS = ('DATA_DIR', *(field.name for field in dataclasses.fields(Env) if field.name not in DERIVED))


def service_data_dir():
	"""The service's data directory (SERVICE_DATA_DIR) for the util tools (they set FINBOT_CHECK_ONLY) run by hand
	outside the service, where systemd's STATE_DIRECTORY is not set: they act on the directory the service reads, not
	on var/ in the checkout. '' for the bot itself, and where the service has none."""
	return SERVICE_DATA_DIR if os.environ.get('FINBOT_CHECK_ONLY') and os.path.isdir(SERVICE_DATA_DIR) else ''


def startup_values(getenv):
	"""The startup settings (finbot.env), computed from getenv(name, default): each key read as its Env field's type
	says, its default the field's where it is unset; then those worked out from them. Raises ConfigError."""
	newer = {new: old for old, new in RENAMED.items()}
	def read(name, default):
		"""getenv's value, or for a key with an old name that one's value where the key is unset or blank."""
		value = getenv(name, default)
		return getenv(newer[name], default) if name in newer and getenv(name, '') == '' else value
	r = _Reader(read)
	readers = {int: r.int, str: r.str}
	keys = {field.name: readers[field.type](field.name, field.default) for field in dataclasses.fields(Env)
		if field.name not in DERIVED}
	r.check()
	data_dir = str(REPO_DIR / (getenv('DATA_DIR') or (getenv('STATE_DIRECTORY') or '').split(':')[0] or
		service_data_dir() or 'var'))
	token = keys['telegramBotToken'].rstrip('/')
	return Env(**keys, data_dir=data_dir, cache_dir=data_dir + '/cache',
		telegram_api=f'https://api.telegram.org/bot{token}/' if token else '')


@dataclasses.dataclass(frozen=True)
class Settings:
	"""The settings: settings.conf, which the bot reads at start and on every reload, each with its default here
	and read as its type says (setting_values). Read them as config.settings.<name> when they are used, never into a
	default or a module constant, so that a reload is seen."""
	admin_only: tuple = ('jobs',) # commands only the admins may use: closed by default, as no one is an admin
	admins: tuple = () # network:id each: telegram:@username (or the user id), slack:U0123ABCD, discord:1234...
	cache: bool = True
	cache_seconds: int = 21600
	country_code: str = 'AU'
	demote_leveraged: bool = True
	demote_volatile: bool = True
	exchange_suffix: str = 'AX' # Yahoo's suffix for the local exchange: a bare ticker Yahoo does not know gets it
	exclude_portfolios: tuple = () # portfolio ids
	future_days: int = 30
	graph: bool = True
	http_timeout: int = 18
	hyperlink: bool = True
	hyperlinkFooter: bool = True
	hyperlinkProvider: str = 'google'
	include_portfolios: tuple = () # portfolio ids
	log_level: str = 'INFO' # what the log shows: one of LOG_LEVELS, and those more severe (lib/log.py)
	log_width: int = 71 # the most characters of a log line that can run long (a request's, a chat message's); 0: no cut
	min_analysts: int = 7 # .buy, .sell, .pe and .peg list only stocks this many analysts cover
	past_days: int = 28
	performance_cache_seconds: int = 2400 # Sharesight performance reports (40 minutes: sharesight_warm runs every 30)
	preload_gap: float = 0.1 # seconds between two charts preloaded to a network (see telegram_preload_chat)
	price_percent: float = 5.0 # the movers' threshold (.movers, .session), named when they were .price
	print_headers: bool = False
	shorts_percent: int = 15
	slack_preload_chat: str = '' # a private channel's id (C0123ABCD): a chart's other periods and portfolios are
	# uploaded there as the chart goes out, so that a press shows them without an upload; empty: off
	telegram_preload_chat: str = '' # the same for Telegram: a private channel's or group's id (-1001234567890)
	timezone: str = 'Australia/Melbourne'
	trades_use_yahoo: bool = True # set False if Yahoo breaks
	volatility_multiplier: float = 2.0


def setting_values(values):
	"""The settings, from settings.conf's {key: value}: each read as its Settings field's type says (a tuple is a list
	of words), its default the field's where the file has none. Raises ConfigError listing every bad value."""
	r = _Reader(values.get)
	readers = {bool: r.bool, int: r.int, float: r.float, str: r.str, tuple: r.words,
		'admin_only': r.blankable_words,
		'exchange_suffix': lambda name, default: r.blankable(name, default).removeprefix('.').upper(), # blank: none
		'country_code': lambda name, default: r.str(name, default).strip().upper(),
		'hyperlinkProvider': lambda name, default: r.choice(name, default, ('google', 'yahoo')),
		'log_level': lambda name, default: r.choice(name, default, LOG_LEVELS),
		'timezone': r.zone}
	read = {field.name: readers.get(field.name, readers[field.type])(field.name, field.default)
		for field in dataclasses.fields(Settings)}
	r.check()
	return Settings(**read)


# settings.conf's keys: what a reload can change
SETTING_KEYS = tuple(field.name for field in dataclasses.fields(Settings))


def print_errors(e):
	"""Log a ConfigError's problems, a line each."""
	for line in e.errors:
		print('ERROR config:', line, file=sys.stderr)

def _fail(e):
	"""Log the configuration errors and exit: finbot does not start with a bad setting."""
	print_errors(e)
	sys.exit(1)


try:
	env = startup_values(os.environ.get)
	settings_path = env.settings_path
	_settings = read_settings(settings_path) or {} # the file's own {key: value}, as the last load or reload read it
	settings = setting_values(_settings)
except ConfigError as e:
	_fail(e)

for _dir in (env.data_dir, env.cache_dir):
	# util/check_config.py, possibly run as root: must not create directories the service user then cannot write
	if os.environ.get('FINBOT_CHECK_ONLY'):
		break
	try:
		os.makedirs(_dir, exist_ok=True)
	except OSError as e: # e.g. read-only filesystem (Lambda)
		print("config: can't create", _dir, e, file=sys.stderr)

def data_file(name):
	"""Where a data file is read from: the user's copy in the data dir if any, else the default shipped in defaults/."""
	user = env.data_dir + '/' + name
	return user if os.path.isfile(user) else str(REPO_DIR / 'defaults' / name)

_data_files = {} # path -> (modification time, parsed JSON)

def data_json(name, default=None):
	"""A data file's JSON (the user's copy or the shipped default, as data_file has it), or `default` when there is
	neither. Parsed again only when the file changes; callers must not modify what they get."""
	path = data_file(name)
	try:
		mtime = os.path.getmtime(path)
	except OSError:
		return default
	if (cached := _data_files.get(path)) and cached[0] == mtime:
		return cached[1]
	with open(path, encoding="utf-8") as f:
		value = json.load(f)
	_data_files[path] = (mtime, value)
	return value


def reload():
	"""Re-read settings.conf and apply it: config.settings is replaced in one assignment, so a request never sees half
	of a reload. All or nothing. Returns one line per change; raises ConfigError (nothing applied) if the file is
	missing, unreadable or invalid."""
	global settings, _settings
	new = read_settings(settings_path)
	if new is None:
		raise ConfigError(f'reload requested but {settings_path} does not exist; nothing reloaded')
	values = setting_values(new)
	changes = [f"{name} {getattr(settings, name)!r} -> {getattr(values, name)!r}" for name in SETTING_KEYS
		if getattr(settings, name) != getattr(values, name)]
	settings, _settings = values, new
	return changes


def check_startup_environment():
	"""For bot.py at start. Settings must come from settings.conf, not from the environment that finbot.env fills."""
	problems = [f'{key} is a setting; move it from finbot.env to {SETTINGS_FILE}'
		for key in SETTING_KEYS if key in os.environ]
	if problems:
		raise ConfigError(problems)


def git_version(checkout=None):
	"""Short hash of the checked-out commit, read straight from the .git directory: no git binary to run, and no
	"dubious ownership" refusal when the service user does not own the checkout. Without one (a Docker image), the
	commit it was built from (FINBOT_COMMIT); 'unknown' when neither can be read."""
	try:
		git = Path(checkout or REPO_DIR) / '.git'
		if git.is_file(): # a linked worktree or submodule: .git is a file saying "gitdir: <path>"
			git = (git.parent / git.read_text().split(':', 1)[1].strip()).resolve()
		# refs of a worktree
		common = (git / (git / 'commondir').read_text().strip()).resolve() if (git / 'commondir').is_file() else git
		head = (git / 'HEAD').read_text().strip()
		if head.startswith('ref:'):
			ref = head.split(':', 1)[1].strip()
			if (common / ref).is_file():
				head = (common / ref).read_text().strip()
			else: # the branch is only in packed-refs
				packed = (common / 'packed-refs').read_text().splitlines()
				head = next((line.split()[0] for line in packed if line.endswith(' ' + ref)), '')
		if re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', head):
			return head[:7]
	except (OSError, IndexError):
		pass
	built = os.environ.get('FINBOT_COMMIT', '')
	return built[:7] if re.fullmatch(r'[0-9a-f]{7,64}', built) else 'unknown'


def startup_report():
	"""Lines for the log at start: where the config came from (counts only; check_config names the problems)."""
	def keys(count):
		"""'1 key', '2 keys'."""
		return f"{count} key{'' if count == 1 else 's'}"
	lines = [f'startup environment ({keys(sum(key in os.environ for key in STARTUP_KEYS))} set)']
	if os.path.isfile(settings_path):
		lines.append(f'{settings_path} ({keys(len(_settings))} set; SIGHUP to reload)')
	else:
		lines.append(f'no {SETTINGS_FILE} in {env.data_dir}, reload unavailable')
	return lines + retired_notes(os.environ, 'finbot.env') + renamed_notes(os.environ, 'finbot.env') + \
		retired_notes(_settings)


def retired_notes(values, file=SETTINGS_FILE):
	"""A line for each key of a file's {key: value} that does nothing any more, saying what to do instead."""
	return [f'{key} in {file} does nothing any more: {instead}' for key, instead in RETIRED.items() if key in values]


def renamed_notes(values, file='finbot.env'):
	"""A line for each key of a file's {key: value} that has a new name: the old one still works, but the new one is
	the one to write (and wins, where both are set)."""
	return [f'{old} in {file} is now {new}: ' + (f'{new} is set too, so this line is ignored' if values.get(new) else
		'it still works, but rename it') for old, new in RENAMED.items() if values.get(old)]


def startup_warnings(startup=None):
	"""Settings in finbot.env (an Env; the running one by default), and keys set in the template
	defaults/settings.conf, that do not stop the start but keep part of the bot from working, or do nothing, a line
	each."""
	s = startup or env
	warnings = []
	if s.slackBotToken and not (s.slackAppToken or s.slackOutgoingWebhook):
		warnings.append('slackBotToken is set but neither slackAppToken nor slackOutgoingWebhook is: finbot hears'
			' nothing from Slack, so its commands and buttons get no answer')
	for key in ('slackOutgoingWebhook', 'slackAppToken'):
		if getattr(s, key) and not s.slackBotToken:
			warnings.append(f'{key} is set but slackBotToken is not: Slack commands will get no reply')
	if s.slackAppToken and s.slackOutgoingWebhook:
		warnings.append('slackAppToken is set but so is slackOutgoingWebhook: Slack posts its updates there'
			' (http mode), and the app-level token is not used')
	if s.slackAppToken and not s.slackAppToken.startswith('xapp-'):
		warnings.append("slackAppToken does not start with xapp-: it must be an app-level token (the app's Basic"
			' Information, App-Level Tokens), not the bot token')
	if s.slackOutgoingWebhook and not (s.slackSigningSecret or s.slackOutgoingToken):
		warnings.append('slackOutgoingWebhook is set but neither slackSigningSecret nor slackOutgoingToken is:'
			' Slack is turned off')
	if s.telegramOutgoingWebhook and not s.telegramSecretToken:
		warnings.append('telegramOutgoingWebhook is set but telegramSecretToken is not: Telegram is turned'
			' off')
	if s.telegramSecretToken and not re.fullmatch(r'[A-Za-z0-9_-]{1,256}', s.telegramSecretToken):
		warnings.append('telegramSecretToken is not 1 to 256 letters, digits, _ or -: Telegram takes no other as the'
			" webhook's secret, so setting the webhook will fail")
	if s.telegramSecretToken and not s.telegramOutgoingWebhook:
		warnings.append('telegramSecretToken is set but telegramOutgoingWebhook is not: finbot fetches its Telegram'
			' updates (pull mode), and the token is not used')
	if s.discordOutgoingWebhook and not s.discordBotToken:
		warnings.append('discordOutgoingWebhook is set but discordBotToken is not: Discord commands will get no reply')
	if s.discordOutgoingWebhook and not re.fullmatch(r'[0-9a-fA-F]{64}', s.discordPublicKey):
		warnings.append("discordOutgoingWebhook is set but discordPublicKey is not the app's public key (64 hex"
			' digits): Discord is turned off')
	if s.discordPublicKey and not s.discordOutgoingWebhook:
		warnings.append('discordPublicKey is set but discordOutgoingWebhook is not: finbot keeps to the Discord gateway'
			' (pull mode), and the key is not used')
	if note := template_note(s.settings_path):
		warnings.append(note)
	return warnings
